import unittest

from counts import word_counts


class WordCountsTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(word_counts(""), {})

    def test_no_words(self):
        self.assertEqual(word_counts("  123 !!! ' 42 "), {})

    def test_basic(self):
        self.assertEqual(word_counts("the cat and the hat"),
                         {"the": 2, "cat": 1, "and": 1, "hat": 1})

    def test_case_insensitive(self):
        self.assertEqual(word_counts("Hello HELLO hello hElLo"), {"hello": 4})

    def test_apostrophes_split(self):
        self.assertEqual(word_counts("don't it's can't"),
                         {"don": 1, "t": 2, "it": 1, "s": 1, "can": 1})

    def test_numbers_split(self):
        self.assertEqual(word_counts("abc123def 4ever abc"),
                         {"abc": 2, "def": 1, "ever": 1})

    def test_punctuation_and_whitespace(self):
        self.assertEqual(word_counts("a,b;\ta\nB-a_b.c"),
                         {"a": 3, "b": 3, "c": 1})

    def test_non_ascii_is_separator(self):
        self.assertEqual(word_counts("café naïve"),
                         {"caf": 1, "na": 1, "ve": 1})

    def test_unicode_case_folding_does_not_create_ascii(self):
        # KELVIN SIGN lowercases to 'k'; dotted capital I lowercases to 'i' + U+0307.
        self.assertEqual(word_counts("K İx"), {"x": 1})

    def test_returns_plain_dict(self):
        self.assertIs(type(word_counts("a a")), dict)


if __name__ == "__main__":
    unittest.main()
